		var dPdA: Double = 0.0
		if (a > xs!!.a_bot) {
			dPdA = 2.0 / xs!!.w_max
		} else {
			dPdA = xs!!.r_bot / cpp.SysMath.Sqrt_d(a * xs!!.s_bot)
		}
		var r: Double = this.rect_triang_getRofA(xs, a)
		return (1.6666666666666667 - ((0.6666666666666666 * dPdA) * r)) * cpp.SysMath.Pow_d(r, 0.6666666666666666)
	}

	open fun rect_round_getYofA(xs: XSectParams?, a: Double): Double {
		if (a > xs!!.a_bot) {
			return xs!!.y_bot + ((a - xs!!.a_bot) / xs!!.w_max)
		}
		var alpha: Double = a / ((F_xsect.PI * xs!!.r_bot) * xs!!.r_bot)
		if (alpha < 0.04) {
			return (2.0 * xs!!.r_bot) * this.getYcircular(alpha)
		}
		return (2.0 * xs!!.r_bot) * this.lookup(alpha, this.tbl!!.Y_Circ, this.tbl!!.N_Y_Circ)
	}

	open fun rect_round_getAofY(xs: XSectParams?, y: Double): Double {
		if (y > xs!!.y_bot) {
			return xs!!.a_bot + ((y - xs!!.y_bot) * xs!!.w_max)
		}
		var theta1: Double = 2.0 * cpp.SysMath.Acos_d(1.0 - (y / xs!!.r_bot))
		return ((0.5 * xs!!.r_bot) * xs!!.r_bot) * (theta1 - cpp.SysMath.Sin_d(theta1))
	}

	open fun rect_round_getWofY(xs: XSectParams?, y: Double): Double {
		if (y > xs!!.y_bot) {
			return xs!!.w_max
		}
		return 2.0 * cpp.SysMath.Sqrt_d(y * ((2.0 * xs!!.r_bot) - y))
	}

	open fun rect_round_getRofA(xs: XSectParams?, a: Double): Double {
		if (a <= 0.0) {
			return 0.0
		}
		if (a > xs!!.a_bot) {
			var y1: Double = (a - xs!!.a_bot) / xs!!.w_max
			var theta1: Double = 2.0 * cpp.SysMath.Asin_d((xs!!.w_max / 2.0) / xs!!.r_bot)
			var p: Double = (xs!!.r_bot * theta1) + (2.0 * y1)
			var arg: Double = (a / xs!!.a_full) - F_xsect.RECT_ROUND_ALFMAX
			if (arg > 0.0) {
				p += (arg / (1.0 - F_xsect.RECT_ROUND_ALFMAX)) * xs!!.w_max
			}
			return a / p
		}
		var y1_2: Double = this.rect_round_getYofA(xs, a)
		var theta1_2: Double = 2.0 * cpp.SysMath.Acos_d(1.0 - (y1_2 / xs!!.r_bot))
		var p_2: Double = xs!!.r_bot * theta1_2
		return a / p_2
	}

	open fun rect_round_getRofY(xs: XSectParams?, y: Double): Double {
		if (y <= 0.0) {
			return 0.0
		}
		if (y > xs!!.y_bot) {
			return this.rect_round_getRofA(xs, this.rect_round_getAofY(xs, y))
		}
		var theta1: Double = 2.0 * cpp.SysMath.Acos_d(1.0 - (y / xs!!.r_bot))
		return ((0.5 * xs!!.r_bot) * (1.0 - cpp.SysMath.Sin_d(theta1))) / theta1
	}

	open fun rect_round_getSofA(xs: XSectParams?, a: Double): Double {
		var alfMax: Double = F_xsect.RECT_ROUND_ALFMAX
		if ((a / xs!!.a_full) > alfMax) {
			return xs!!.s_max + (((xs!!.s_full - xs!!.s_max) * ((a / xs!!.a_full) - alfMax)) / (1.0 - alfMax))
		}
		if (a > xs!!.a_bot) {
			return a * cpp.SysMath.Pow_d(this.rect_round_getRofA(xs, a), 0.6666666666666666)
		}
		var aFull: Double = (F_xsect.PI * xs!!.r_bot) * xs!!.r_bot
		var alpha: Double = a / aFull
		var sFull: Double = xs!!.s_bot
		if (alpha < 0.04) {
			return sFull * this.getScircular(alpha)
		}
		return sFull * this.lookup(alpha, this.tbl!!.S_Circ, this.tbl!!.N_S_Circ)
	}

	open fun rect_round_getdSdA(xs: XSectParams?, a: Double): Double {
		var alfMax: Double = F_xsect.RECT_ROUND_ALFMAX
		if ((a / xs!!.a_full) > alfMax) {
			return (xs!!.s_full - xs!!.s_max) / ((1.0 - alfMax) * xs!!.a_full)
		}
		if (a > xs!!.a_bot) {
			var r: Double = this.rect_round_getRofA(xs, a)
			var dPdA: Double = 2.0 / xs!!.w_max
			return (1.6666666666666667 - ((0.6666666666666666 * dPdA) * r)) * cpp.SysMath.Pow_d(r, 0.6666666666666666)
		}
		return this.generic_getdSdA(xs, a)
	}

	open fun mod_basket_getYofA(xs: XSectParams?, a: Double): Double {
		if (a <= (xs!!.a_full - xs!!.a_bot)) {
			return a / xs!!.w_max
		}
		var alpha: Double = (xs!!.a_full - a) / ((F_xsect.PI * xs!!.r_bot) * xs!!.r_bot)
		var y1: Double = 0.0
		if (alpha < 0.04) {
			y1 = this.getYcircular(alpha)
		} else {
			y1 = this.lookup(alpha, this.tbl!!.Y_Circ, this.tbl!!.N_Y_Circ)
		}
		y1 = (2.0 * xs!!.r_bot) * y1
		return xs!!.y_full - y1
	}

	open fun mod_basket_getAofY(xs: XSectParams?, y: Double): Double {
		if (y <= (xs!!.y_full - xs!!.y_bot)) {
			return y * xs!!.w_max
		}
		var y1: Double = xs!!.y_full - y
		var theta1: Double = 2.0 * cpp.SysMath.Acos_d(1.0 - (y1 / xs!!.r_bot))
		var a1: Double = ((0.5 * xs!!.r_bot) * xs!!.r_bot) * (theta1 - cpp.SysMath.Sin_d(theta1))
		return xs!!.a_full - a1
	}

	open fun mod_basket_getWofY(xs: XSectParams?, y: Double): Double {
		if (y <= 0.0) {
			return 0.0
		}
		if (y <= (xs!!.y_full - xs!!.y_bot)) {
			return xs!!.w_max
		}
		var y1: Double = xs!!.y_full - y
		return 2.0 * cpp.SysMath.Sqrt_d(y1 * ((2.0 * xs!!.r_bot) - y1))
	}

	open fun mod_basket_getRofA(xs: XSectParams?, a: Double): Double {
		if (a <= (xs!!.a_full - xs!!.a_bot)) {
			return a / (xs!!.w_max + ((2.0 * a) / xs!!.w_max))
		}
		var y1: Double = xs!!.y_full - this.mod_basket_getYofA(xs, a)
		var theta1: Double = 2.0 * cpp.SysMath.Acos_d(1.0 - (y1 / xs!!.r_bot))
		var p: Double = (xs!!.s_bot - theta1) * xs!!.r_bot
		y1 = xs!!.y_full - xs!!.y_bot
		p = (p + (2.0 * y1)) + xs!!.w_max
		return a / p
	}

	open fun mod_basket_getdSdA(xs: XSectParams?, a: Double): Double {
		if ((a <= (xs!!.a_full - xs!!.a_bot)) && ((a / xs!!.a_full) > 1E-30)) {
			var r: Double = a / (xs!!.w_max + ((2.0 * a) / xs!!.w_max))
			var dPdA: Double = 2.0 / xs!!.w_max
			return (1.6666666666666667 - ((0.6666666666666666 * dPdA) * r)) * cpp.SysMath.Pow_d(r, 0.6666666666666666)
		}
		return this.generic_getdSdA(xs, a)
	}

	open fun trapez_getAofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.trapezAofY(y, xs!!.y_bot, xs!!.s_bot)
	}

	open fun trapez_getWofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.trapezWofY(y, xs!!.y_bot, xs!!.s_bot)
	}

	open fun trapez_getYofA(xs: XSectParams?, a: Double): Double {
		if (xs!!.s_bot == 0.0) {
			return a / xs!!.y_bot
		}
		return (cpp.SysMath.Sqrt_d((xs!!.y_bot * xs!!.y_bot) + ((4.0 * xs!!.s_bot) * a)) - xs!!.y_bot) / (2.0 * xs!!.s_bot)
	}

	open fun trapez_getRofA(xs: XSectParams?, a: Double): Double {
		return a / (xs!!.y_bot + (this.trapez_getYofA(xs, a) * xs!!.r_bot))
	}

	open fun trapez_getRofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.trapezRofY(y, xs!!.y_bot, xs!!.s_bot, xs!!.r_bot)
	}

	open fun trapez_getdSdA(xs: XSectParams?, a: Double): Double {
		if ((a / xs!!.a_full) <= 1E-30) {
			return this.generic_getdSdA(xs, a)
		}
		var r: Double = this.trapez_getRofA(xs, a)
		var dPdA: Double = xs!!.r_bot / cpp.SysMath.Sqrt_d((xs!!.y_bot * xs!!.y_bot) + ((4.0 * xs!!.s_bot) * a))
		return (1.6666666666666667 - ((0.6666666666666666 * dPdA) * r)) * cpp.SysMath.Pow_d(r, 0.6666666666666666)
	}

	open fun triang_getAofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.triangAofY(y, xs!!.s_bot)
	}

	open fun triang_getWofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.triangWofY(y, xs!!.s_bot)
	}

	open fun triang_getYofA(xs: XSectParams?, a: Double): Double {
		return cpp.SysMath.Sqrt_d(a / xs!!.s_bot)
	}

	open fun triang_getRofA(xs: XSectParams?, a: Double): Double {
		return a / ((2.0 * this.triang_getYofA(xs, a)) * xs!!.r_bot)
	}

	open fun triang_getRofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.triangRofY(y, xs!!.s_bot, xs!!.r_bot)
	}

	open fun triang_getdSdA(xs: XSectParams?, a: Double): Double {
		if ((a / xs!!.a_full) <= 1E-30) {
			return this.generic_getdSdA(xs, a)
		}
		var r: Double = this.triang_getRofA(xs, a)
		var dPdA: Double = xs!!.r_bot / cpp.SysMath.Sqrt_d(a * xs!!.s_bot)
		return (1.6666666666666667 - ((0.6666666666666666 * dPdA) * r)) * cpp.SysMath.Pow_d(r, 0.6666666666666666)
	}

	open fun parab_getAofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.parabAofY(y, xs!!.r_bot)
	}

	open fun parab_getWofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.parabWofY(y, xs!!.r_bot)
	}

	open fun parab_getYofA(xs: XSectParams?, a: Double): Double {
		return cpp.SysMath.Pow_d((0.75 * a) / xs!!.r_bot, 0.6666666666666666)
	}

	open fun parab_getPofY(xs: XSectParams?, y: Double): Double {
		var x: Double = (2.0 * cpp.SysMath.Sqrt_d(y)) / xs!!.r_bot
		var t: Double = cpp.SysMath.Sqrt_d(1.0 + (x * x))
		return ((0.5 * xs!!.r_bot) * xs!!.r_bot) * ((x * t) + cpp.SysMath.Log_d(x + t))
	}

	open fun parab_getRofY(xs: XSectParams?, y: Double): Double {
		if (y <= 0.0) {
			return 0.0
		}
		return this.parab_getAofY(xs, y) / this.parab_getPofY(xs, y)
	}

	open fun parab_getRofA(xs: XSectParams?, a: Double): Double {
		if (a <= 0.0) {
			return 0.0
		}
		return a / this.parab_getPofY(xs, this.parab_getYofA(xs, a))
	}

	open fun powerfunc_getAofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.powerfuncAofY(y, xs!!.s_bot, xs!!.r_bot)
	}

	open fun powerfunc_getWofY(xs: XSectParams?, y: Double): Double {
		return F_xsect_shape.powerfuncWofY(y, xs!!.s_bot, xs!!.r_bot)
	}

	open fun powerfunc_getYofA(xs: XSectParams?, a: Double): Double {
		return cpp.SysMath.Pow_d(a / xs!!.r_bot, 1.0 / (xs!!.s_bot + 1.0))
	}

	open fun powerfunc_getPofY(xs: XSectParams?, y: Double): Double {
		var dy1: Double = 0.02 * xs!!.y_full
		var h: Double = ((xs!!.s_bot + 1.0) * xs!!.r_bot) / 2.0
		var m: Double = xs!!.s_bot
		var p: Double = 0.0
		var y1: Double = 0.0
		var x1: Double = 0.0
		var x2: Double = 0.0
		var y2: Double = 0.0
		var dx: Double = 0.0
		var dy: Double = 0.0
		__L1@ do {
			y2 = y1 + dy1
			if (y2 > y) {
				y2 = y
			}
			x2 = h * cpp.SysMath.Pow_d(y2, m)
			dx = x2 - x1
			dy = y2 - y1
			p += cpp.SysMath.Sqrt_d((dx * dx) + (dy * dy))
			x1 = x2
			y1 = y2
		} while (y2 < y)
		return 2.0 * p
	}

	open fun powerfunc_getRofY(xs: XSectParams?, y: Double): Double {
		if (y <= 0.0) {
			return 0.0
		}
		return this.powerfunc_getAofY(xs, y) / this.powerfunc_getPofY(xs, y)
	}

	open fun powerfunc_getRofA(xs: XSectParams?, a: Double): Double {
		if (a <= 0.0) {
			return 0.0
		}
		return a / this.powerfunc_getPofY(xs, this.powerfunc_getYofA(xs, a))
	}

	open fun getAofY(xs: XSectParams?, y: Double): Double {
		if (y <= 0.0) {
			return 0.0
		}
		if (xs!!.y_full <= 0.0) {
			return 0.0
		}
		var y_norm: Double = y / xs!!.y_full
		when (xs!!.type) {
			24, 1 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_Circ, this.tbl!!.N_A_Circ)
			}
			2 -> {
				return this.filled_circ_getAofY(xs, y)
			}
			15 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_Egg, this.tbl!!.N_A_Egg)
			}
			16 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_Horseshoe, this.tbl!!.N_A_Horseshoe)
			}
			17 -> {
				return xs!!.a_full * this.invLookup(y_norm, this.tbl!!.Y_Gothic, this.tbl!!.N_Y_Gothic, this.tbl!!.lut(xsect_LutId.Y_Gothic))
			}
			18 -> {
				return xs!!.a_full * this.invLookup(y_norm, this.tbl!!.Y_Catenary, this.tbl!!.N_Y_Catenary, this.tbl!!.lut(xsect_LutId.Y_Catenary))
			}
			19 -> {
				return xs!!.a_full * this.invLookup(y_norm, this.tbl!!.Y_SemiEllip, this.tbl!!.N_Y_SemiEllip, this.tbl!!.lut(xsect_LutId.Y_SemiEllip))
			}
			20 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_Baskethandle, this.tbl!!.N_A_Baskethandle)
			}
			21 -> {
				return xs!!.a_full * this.invLookup(y_norm, this.tbl!!.Y_SemiCirc, this.tbl!!.N_Y_SemiCirc, this.tbl!!.lut(xsect_LutId.Y_SemiCirc))
			}
			12 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_HorizEllipse, this.tbl!!.N_A_HorizEllipse)
			}
			13 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_VertEllipse, this.tbl!!.N_A_VertEllipse)
			}
			14 -> {
				return xs!!.a_full * this.lookup(y_norm, this.tbl!!.A_Arch, this.tbl!!.N_A_Arch)
			}
			3, 4 -> {
				return F_xsect_shape.rectAofY(y, xs!!.w_max)
			}
			9 -> {
				return this.rect_triang_getAofY(xs, y)
			}
			10 -> {
				return this.rect_round_getAofY(xs, y)
			}
			11 -> {
				return this.mod_basket_getAofY(xs, y)
			}
			5 -> {
				return this.trapez_getAofY(xs, y)
			}
			6 -> {
				return this.triang_getAofY(xs, y)
			}
			7 -> {
				return this.parab_getAofY(xs, y)
			}
			8 -> {
				return this.powerfunc_getAofY(xs, y)
			}
			22, 23, 25 -> {
				if (!((xs!!.area_tbl)!!.get_IsNull())) {
					return xs!!.a_full * this.lookup(y_norm, xs!!.area_tbl, xs!!.transect_tbl_size)
				}
				return 0.0
			}
			else -> {
				return 0.0
			}
		}
		throw IllegalStateException("unreachable")
	}

	open fun getWofY(xs: XSectParams?, y: Double): Double {
		var y_norm: Double = y / xs!!.y_full
		when (xs!!.type) {
			24, 1 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_Circ, this.tbl!!.N_W_Circ)
			}
			2 -> {
				var yn: Double = (y + xs!!.y_bot) / (xs!!.y_full + xs!!.y_bot)
				return xs!!.w_max * this.lookup(yn, this.tbl!!.W_Circ, this.tbl!!.N_W_Circ)
			}
			15 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_Egg, this.tbl!!.N_W_Egg)
			}
			16 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_Horseshoe, this.tbl!!.N_W_Horseshoe)
			}
			17 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_Gothic, this.tbl!!.N_W_Gothic)
			}
			18 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_Catenary, this.tbl!!.N_W_Catenary)
			}
			19 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_SemiEllip, this.tbl!!.N_W_SemiEllip)
			}
			20 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_BasketHandle, this.tbl!!.N_W_BasketHandle)
			}
			21 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_SemiCirc, this.tbl!!.N_W_SemiCirc)
			}
			12 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_HorizEllipse, this.tbl!!.N_W_HorizEllipse)
			}
			13 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_VertEllipse, this.tbl!!.N_W_VertEllipse)
			}
			14 -> {
				return xs!!.w_max * this.lookup(y_norm, this.tbl!!.W_Arch, this.tbl!!.N_W_Arch)
			}
			3 -> {
				return F_xsect_shape.rectClosedWofY(y_norm, xs!!.w_max)
			}
			4 -> {
				return xs!!.w_max
			}
			9 -> {
				return this.rect_triang_getWofY(xs, y)
			}
			10 -> {
				return this.rect_round_getWofY(xs, y)
			}
			11 -> {
				return this.mod_basket_getWofY(xs, y)
			}
			5 -> {
				return this.trapez_getWofY(xs, y)
			}
			6 -> {
				return this.triang_getWofY(xs, y)
			}
			7 -> {
				return this.parab_getWofY(xs, y)
			}
			8 -> {
				return this.powerfunc_getWofY(xs, y)
			}
			22, 23, 25 -> {
				if (!((xs!!.width_tbl)!!.get_IsNull())) {
					return xs!!.w_max * this.lookup(y_norm, xs!!.width_tbl, xs!!.transect_tbl_size)
				}
				return 0.0
			}
			else -> {
				return 0.0
			}
		}
		throw IllegalStateException("unreachable")
	}

	open fun getRofY(xs: XSectParams?, y: Double): Double {
		var y_norm: Double = y / xs!!.y_full
		when (xs!!.type) {
			24, 1 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_Circ, this.tbl!!.N_R_Circ)
			}
			2 -> {
				if (xs!!.y_bot == 0.0) {
					return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_Circ, this.tbl!!.N_R_Circ)
				}
				return this.filled_circ_getRofY(xs, y)
			}
			15 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_Egg, this.tbl!!.N_R_Egg)
			}
			16 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_Horseshoe, this.tbl!!.N_R_Horseshoe)
			}
			20 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_Baskethandle, this.tbl!!.N_R_Baskethandle)
			}
			12 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_HorizEllipse, this.tbl!!.N_R_HorizEllipse)
			}
			13 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_VertEllipse, this.tbl!!.N_R_VertEllipse)
			}
			14 -> {
				return xs!!.r_full * this.lookup(y_norm, this.tbl!!.R_Arch, this.tbl!!.N_R_Arch)
			}
			9 -> {
				return this.rect_triang_getRofY(xs, y)
			}
			10 -> {
