	open fun getAofS(xs: XSectParams?, s__p: Double): Double {
		val s: cpp.RefD.Cell = cpp.RefD.Cell(s__p)
		var psi: Double = s.v / xs!!.s_full
		if (s.v <= 0.0) {
			return 0.0
		}
		if (s.v > xs!!.s_max) {
			s.v = xs!!.s_max
		}
		when (xs!!.type) {
			0 -> {
				return 0.0
			}
			24, 1 -> {
				return this.circ_getAofS(xs, s.v)
			}
			15 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_Egg, this.tbl!!.N_S_Egg, this.tbl!!.lut(xsect_LutId.S_Egg))
			}
			16 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_Horseshoe, this.tbl!!.N_S_Horseshoe, this.tbl!!.lut(xsect_LutId.S_Horseshoe))
			}
			17 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_Gothic, this.tbl!!.N_S_Gothic, this.tbl!!.lut(xsect_LutId.S_Gothic))
			}
			18 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_Catenary, this.tbl!!.N_S_Catenary, this.tbl!!.lut(xsect_LutId.S_Catenary))
			}
			19 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_SemiEllip, this.tbl!!.N_S_SemiEllip, this.tbl!!.lut(xsect_LutId.S_SemiEllip))
			}
			20 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_BasketHandle, this.tbl!!.N_S_BasketHandle, this.tbl!!.lut(xsect_LutId.S_BasketHandle))
			}
			21 -> {
				return xs!!.a_full * this.invLookup(psi, this.tbl!!.S_SemiCirc, this.tbl!!.N_S_SemiCirc, this.tbl!!.lut(xsect_LutId.S_SemiCirc))
			}
			else -> {
				var a1: Double = 0.0
				var a2: Double = 0.0
				var sh: Int = xs!!.type
				var a_max: Double = if ((sh == XSectShape.CUSTOM) || (sh == XSectShape.IRREGULAR)) xs!!.a_bot else xs!!.a_full * this.getAmax(xs)
				if (((s.v <= xs!!.s_max) && (s.v >= xs!!.s_full)) && (xs!!.s_max != xs!!.s_full)) {
					a1 = xs!!.a_full
					a2 = a_max
				} else {
					a1 = 0.0
					a2 = a_max
				}
				var a: cpp.RefD.Cell = cpp.RefD.Cell(0.5 * (a1 + a2))
				var tol: Double = 0.0001 * xs!!.a_full
				var __b1: DoubleArray? = doubleArrayOf(a.v)
				cpp.Mv.Back__ID(this.findroot_Newton(a1, a2, cpp.PtrD(__b1, 0L), tol, FN57 __lam2@{ aa, f, df ->
				(f!!.ref_Deref())!!.set(this.getSofA(xs, aa) - s.v)
				(df!!.ref_Deref())!!.set(this.getdSdA(xs, aa))
				return@__lam2
			}), a, __b1)
				return a.v
			}
		}
		throw IllegalStateException("unreachable")
	}

	open fun getAmax(xs: XSectParams?): Double {
		if ((xs!!.type >= 0) && (xs!!.type <= 25)) {
