		}
		return 1.0
	}

	open fun getYcrit(xs: XSectParams?, q: Double): Double {
		if (q <= 0.0) {
			return 0.0
		}
		var q2g: Double = (q * q) / F_xsect.GRAVITY
		if (q2g == 0.0) {
			return 0.0
		}
		var y: Double = 0.0
		__sw1@ do {
			when (xs!!.type) {
				0 -> {
					return 0.0
				}
				4, 3 -> {
					y = cpp.SysMath.Pow_d(q2g / (xs!!.w_max * xs!!.w_max), 0.3333333333333333)
					break@__sw1
				}
				6 -> {
					y = cpp.SysMath.Pow_d((2.0 * q2g) / (xs!!.s_bot * xs!!.s_bot), 0.2)
					break@__sw1
				}
				7 -> {
					y = cpp.SysMath.Pow_d((0.84375 * q2g) / (xs!!.r_bot * xs!!.r_bot), 0.25)
					break@__sw1
				}
				8 -> {
					y = 1.0 / ((2.0 * xs!!.s_bot) + 3.0)
					y = cpp.SysMath.Pow_d((q2g * (xs!!.s_bot + 1.0)) / (xs!!.r_bot * xs!!.r_bot), y)
					break@__sw1
				}
				else -> {
					var qCritical: FN108? = FN108 __lam2@{ yc, qTarget ->
				var a: Double = this.getAofY(xs, yc)
				var w: Double = this.getWofY(xs, yc)
				if (w > 0.0) {
					return@__lam2 (a * cpp.SysMath.Sqrt_d((F_xsect.GRAVITY * a) / w)) - qTarget
				}
				return@__lam2 -qTarget
			}
					var y0: Double = 1.01 * cpp.SysMath.Pow_d(q2g / xs!!.y_full, 0.25)
					if (y0 >= xs!!.y_full) {
						y0 = 0.97 * xs!!.y_full
					}
					var r: Double = xs!!.a_full / (((F_xsect.PI / 4.0) * xs!!.y_full) * xs!!.y_full)
					if ((r >= 0.5) && (r <= 2.0)) {
						var N_INC: Int = 25
						var dy: Double = xs!!.y_full / N_INC.toDouble()
						var i1: Int = cpp.Conv.D2I(y0 / dy)
						var q0: Double = qCritical!!.invoke(i1.toDouble() * dy, 0.0)
						if (q0 < q) {
							y = xs!!.y_full
							var i: Int = i1 + 1
							__L3@ while (i <= N_INC) {
								var qc: Double = qCritical!!.invoke(i.toDouble() * dy, 0.0)
								if (qc >= q) {
									y = (((q - q0) / (qc - q0)) + (i - 1).toDouble()) * dy
									break@__L3
								}
								q0 = qc
								i++
							}
						} else {
							y = 0.0
							var i_2: Int = i1 - 1
							__L4@ while (i_2 >= 0) {
								var qc_2: Double = qCritical!!.invoke(i_2.toDouble() * dy, 0.0)
								if (qc_2 < q) {
									y = (((q - qc_2) / (q0 - qc_2)) + i_2.toDouble()) * dy
									break@__L4
								}
								q0 = qc_2
								i_2--
							}
						}
					} else {
						var y1: Double = 0.0
						var y2: Double = 0.99 * xs!!.y_full
						var q2: Double = qCritical!!.invoke(y2, 0.0)
						if (q2 < q) {
							y = xs!!.y_full
							break@__sw1
						}
						var q0_2: Double = qCritical!!.invoke(y0, 0.0)
						var q1: Double = qCritical!!.invoke(0.5 * xs!!.y_full, 0.0)
						if (q0_2 > q) {
							y2 = y0
							if (q1 < q) {
								y1 = 0.5 * xs!!.y_full
							}
						} else {
							y1 = y0
							if (q1 > q) {
								y2 = 0.5 * xs!!.y_full
							}
						}
						y = this.findroot_Ridder(y1, y2, 0.001, FN106 __lam5@{ yc_2 ->
				return@__lam5 qCritical!!.invoke(yc_2, q)
			})
					}
					break@__sw1
				}
			}
		} while (false)
		return cpp.M.min_d_d(y, xs!!.y_full)
	}

